          status = "failed"
        elif SENTINEL_FOUND = false:
          status = "incomplete"   # EXIT_CODE=0 but no proof of completion
        elif SENTINEL_FOUND = true:
          # Parse sentinel JSON for self-reported status
          sentinel_status = parse JSON from SENTINEL → .status
          if sentinel_status = "completed":
            status = "completed"
          elif sentinel_status = "failed":
            status = "failed"  # Agent self-reported failure
          else:
            status = sentinel_status  # Pass through any other value
